/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustDirectDebitMandateMandateReference extends UPSPricingAttributeCustDirectDebitMandate implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, MandateReference);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by MandateReference
    {
        if (! ret.in(custDirectDebitMandate.MandateReference))
        {
            ret.add(custDirectDebitMandate.MandateReference);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, MandateReference));
    qbr.value(queryValue(_value));
}
